        prev = opp.get('previous_trace', {})
        if prev and prev.get('bid') is not None and prev.get('error') in (None, '', 'none'):
            prev_bids.append(prev.get('bid', 0))

    highest_prev = max(prev_bids) if prev_bids else 0
    avg_prev = (sum(prev_bids) / len(prev_bids)) if prev_bids else 0

    if hp <= 1:
        base = 69
    elif hp <= 2 or no_water >= 2:
        base = 63
    elif hp <= 4 or no_water >= 1:
        base = 52
    else:
        if supply >= 23:
            base = 24
        elif supply >= 20:
            base = 31
        elif supply >= 17:
            base = 39
        else:
            base = 47

    if highest_prev >= 64:
        if hp > 4 and no_water == 0:
            bid = max(12, base - 10)
        else:
            bid = max(base, 61)
    elif highest_prev >= 50:
        if hp <= 4 or no_water >= 1:
            bid = max(base, highest_prev + 2)
        else:
            bid = max(base, highest_prev - 6)
    elif highest_prev > 0:
        bid = max(base, avg_prev + 3)
    else:
        bid = base

    if desperate_count >= 2 and hp > 4 and no_water == 0:
        bid -= 6
    elif desperate_count >= 1 and (hp <= 3 or no_water >= 1):
        bid += 4

    if rich_count == len(alive_opponents) and hp > 4 and no_water == 0:
