def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 150
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15

    supply = float(day_context.get('supply', 0.0))
    day = int(day_context.get('day', 0))

    hp = float(my_status.get('hp', 0.0))
    budget = float(my_status.get('budget', 0.0))
    no_water_days = int(my_status.get('no_water_days', 0))

    alive_opponents = []
    for opp in opponents_status.values():
        if opp.get('alive', False):
            alive_opponents.append(opp)

    # Base safety bid: ensure we can still afford multiple days.
    # If supply is near the requirement, bid more; if abundant, bid less.
    supply_ratio = 0.0
    if WATER_REQ > 0:
        supply_ratio = supply / float(WATER_REQ)

    # Conservative target fraction based on supply
    if supply_ratio <= 1.05:
        base_frac = 0.55
    elif supply_ratio <= 1.4:
        base_frac = 0.45
    else:
        base_frac = 0.35

    # Read yesterday bids for immediate reaction
    prev_bids = []
    for opp in alive_opponents:
        prev = opp.get('previous_trace', {})
        if isinstance(prev, dict):
            b = prev.get('bid', None)
            if b is not None:
                try:
                    prev_bids.append(float(b))
                except Exception:
                    pass

    high_pressure = False
    high_bid = None
    if prev_bids:
        high_bid = max(prev_bids)
        # Threshold tuned to DAILY_SALARY scale
        if high_bid >= DAILY_SALARY * 0.85:
            high_pressure = True

    # Survival override
    if hp <= 2.0 or no_water_days >= 2:
        # Spend enough to likely win water when survival is critical
        target = DAILY_SALARY * 0.9
    elif high_pressure:
        # Match/beat the observed high pressure
        target = min(budget, max(DAILY_SALARY * 0.3, (high_bid + 1.5)))
    else:
        # Moderate bid: conserve budget unless yesterday showed high competition
        target = DAILY_SALARY * base_frac

    # Cap by budget and keep within a reasonable range relative to supply
    # If supply is low, allow higher spending.
    if supply_ratio <= 1.05:
        target = max(target, DAILY_SALARY * 0.5)

    bid = min(budget, target)

    # Ensure bid is non-negative and not absurdly large
    if bid < 0.0:
        bid = 0.0

    return bid

